sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var switchTrade = newValue;
    var RegularExp = /^[A-Z]{2}-[A-Z]{4}-[RD]-[0-9]{6}-[0-9][0-9]-[0-9]-20\d\d(0[1-9]|1[0-2])(0[1-9]|[12][0-9]|3[01])$/i;
    var result = RegularExp.test(switchTrade);
    if (result == false) {
        g_form.addErrorMessage(" Please enter in format XX-XXXX-Z-NNNNNN-NN-N-YYYYMMDD");
        g_form.setValue('corresponding_switch_trade_id', '');
    }
	else
	{
		g_form.clearMessages();
	}	



}
